import pandas as pd
import os

# Load all available experiments
dfs = {}
for exp_id in [1,2,3,4,6,7,8]:
    path = f"experiment_{exp_id}_csv"
    if os.path.exists(path):
        try:
            dfs[exp_id] = pd.read_csv(path)
            print(f"\n=== Experiment {exp_id}: {len(dfs[exp_id])} rows, columns: {list(dfs[exp_id].columns)}")
            print(dfs[exp_id].describe().round(2))
        except Exception as e:
            print(f"Experiment {exp_id}: Error - {e}")
    else:
        print(f"Experiment {exp_id}: file not found")

# Check for intervention markers
for exp_id, df in dfs.items():
    int_cols = [c for c in df.columns if 'intervene' in c.lower() or 'diuretic' in c.lower() or 'adherence' in c.lower() or 'program' in c.lower()]
    if int_cols:
        print(f"\nExp {exp_id} intervention columns: {int_cols}")
        for c in int_cols:
            print(f"  {c}: {df[c].value_counts().head(10)}")
